#--------------calcul du score----------------
def bonus(ch): 
    nbMaj,nbMin,nbCar=0,0,0
    for i in range(len(ch)):
        if "A"<=ch[i]<="Z":
            nbMaj+=1
        elif "a"<=ch[i]<="z":
            nbMin+=1
        else:
            nbCar+=1
    return (len(ch)*4)+(len(ch)-nbMaj*2)+(len(ch)-nbMin*2)+nbCar*5

def penalit(psw,x,y):
    maxlen=0
    ch=""
    for i in range(len(ch)):
        if x<=psw[i]<=y :
            ch+=psw[i]
        else:
            if len(ch)>maxlen:
                maxlen=len(ch)
            ch=""
    return len(ch)*2
#---------------------------------------------

def evaluation():
    f1=open("motdepass.txt","r")
    f2=open("evaluation.dat","wb")
    ch=f1.readline().strip()
    while ch!="":
        e={}
        e["psw"]=ch
        p_plsmaj=penalit(ch,"A","Z")
        p_plsmin=penalit(ch,"a","z")
        e["score"]=bonus(ch)-(p_plsmaj+p_plsmin)
        if e["score"]<20:
            e["force"]="Tres faible"
        elif e["score"]<40:
            e["force"]="Faible"
        elif e["score"]<60:
            e["force"]="Moyen"
        elif e["score"]<80:
            e["force"]="Fort"
        else :
            e["force"]="Tres fort"
        dump(e,f2)
        ch=f1.readline().strip()
    f1.close()
    f2.close()
